150	header :focus-visible,
151	.contacts-info :focus-visible,
152	.price-card.featured :focus-visible {
153	    outline-color: var(--accent-on-ink);
154	}
155	
156	.form-group input:focus-visible,
157	.form-group select:focus-visible,
158	.form-group textarea:focus-visible { outline: none; }
159	
160	/* ==========================================================================
161	   14. RESPONSIVE
162	   ========================================================================== */
163	@media (max-width: 900px) {
164	    .features-grid { grid-template-columns: 1fr; }
165	    .contacts-wrapper { grid-template-columns: 1fr; }
166	    .comparison-slider { height: 340px; }
167	}
168	
169	@media (max-width: 640px) {
170	    .header-container {
171	        padding: 0 var(--s4);
172	        gap: var(--s3);
173	    }
174	
175	    .page-container {
176	        padding-left: var(--s4);
177	        padding-right: var(--s4);
178	        padding-bottom: var(--s7);
179	    }
180	
181	    .hero-stats { flex-direction: column; }
182	
183	    .stat-item + .stat-item {
184	        border-left: 0;
185	        border-top: 1px solid var(--border);
186	    }
187	
188	    .form-grid-2 { grid-template-columns: 1fr; }
189	
190	    .order-form,
191	    .contacts-info,
192	    .price-card,
193	    .modal-content,
194	    .portfolio-grid > .portfolio-card,
195	    .page-about .portfolio-card { padding: var(--s5); }
196	
197	    .comparison-slider { height: 280px; }
198	
199	    .portfolio-before-after-section { margin-top: var(--s8); }
200	}
201	
