203	   15. REDUCED MOTION
204	   ========================================================================== */
205	@media (prefers-reduced-motion: reduce) {
206	    html { scroll-behavior: auto; }
207	
208	    *, *::before, *::after {
209	        animation-duration: .01ms !important;
210	        animation-iteration-count: 1 !important;
211	        transition-duration: .01ms !important;
212	        scroll-behavior: auto !important;
213	    }
214	
215	    .feature-card:hover,
216	    .service-card:hover,
217	    .portfolio-card:hover,
218	    .btn-primary:hover { transform: none; }
