    --fs-display:   clamp(2.25rem, 1.6rem + 2.6vw, 3.4rem);
    --fs-title:     clamp(1.9rem, 1.5rem + 1.6vw, 2.6rem);
    --fs-section:   clamp(1.5rem, 1.3rem + 0.9vw, 1.95rem);
    --fs-card:      1.2rem;
    --fs-body:      1rem;
    --fs-sm:        0.875rem;
    --fs-micro:     0.72rem;

    /* --- Space (4px base) --- */
    --s1: 4px;  --s2: 8px;  --s3: 12px; --s4: 16px; --s5: 24px;
    --s6: 32px; --s7: 48px; --s8: 64px; --s9: 96px;

    /* --- Radii --- */
