    --sh-2: 0 2px 4px rgba(23, 36, 34, .04),
            0 10px 20px -8px rgba(23, 36, 34, .10);
    --sh-3: 0 4px 8px rgba(23, 36, 34, .05),
            0 20px 40px -16px rgba(23, 36, 34, .20);

    /* --- Layout --- */
    --header-h: 68px;
    --wrap: 1200px;

    /* --- Motion --- */
    --t-fast: 140ms cubic-bezier(.2, .6, .3, 1);
